files.content:
* {
  box-sizing: border-box;
}

html {
  block-size: 100%;
}

body {
  position: relative;
  display: flex;
  justify-content: center;
  align-items: center;
  margin: 0;
  padding: 50px;
  font-family: 'Open Sans', sans-serif;
  background-image: url(https://code.s3.yandex.net/web-code/images/dotted-l.svg);
  block-size: 100%;
}

.content {
  /* пропишите фильтр здесь */
  filter: blur(0.3rem);
}

.header__title {
  margin: 0;
  border: 1px solid #000;
  padding: 20px 0;
  font-weight: 800;
  font-size: 38px;
  text-align: center;
  text-transform: uppercase;
}

.menu__list {
  display: flex;
  margin: 0;
  padding: 0;
  list-style: none;
  inline-size: 100%;
}

.menu__item {
  margin: 0;
  border: 1px solid #000;
  padding: 20px 10px;
  cursor: pointer;
  inline-size: calc(100% / 3);
}

.menu__item a {
  display: block;
  margin: 0;
  font-weight: 800;
  font-size: 24px;
  text-align: center;
  text-transform: uppercase;
}

.card__title {
  align-self: flex-start;
  font-weight: 400;
  font-size: 16px;
  -webkit-hyphens: auto;
  hyphens: auto;
}

.container {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
}

.card {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  align-items: center;
  border: 1px solid black;
  padding: 20px;
  background-color: white;
}

.card__image {
  border: 1px solid #000;
  inline-size: 100%;
}

.card__description {
  inline-size: 100%;
}

.card__button {
  border: 1px solid #000;
  padding: 20px 0;
  color: #000;
  font-family: inherit;
  font-weight: 800;
  font-size: inherit;
  text-transform: uppercase;
  background-color: #ffc802;
  inline-size: 100%;
}

.card:nth-child(1) {
  background-color: #c4c4c4;
}

.card:nth-child(2) {
  background-color: #feafe8;
}

.card:nth-child(3) {
  background-color: #80d994;
}

button:hover {
  box-shadow: inset 0 0 0 100px rgb(0 0 0 / 0.15);
  cursor: pointer;
}

button:focus-visible {
  outline: 2px solid #000;
  outline-offset: 0;
}

.popup {
  position: absolute;
  display: grid;
  place-items: center;
  border: 5px solid black;
  padding: 10px;
  text-align: center;
  background-color: white;
  inset-block-start: 30%;
  inline-size: 320px;
  block-size: 200px;
}

.popup__close-button {
  position: absolute;
  border: none;
  background-color: transparent;
  cursor: pointer;
  inset-block-start: 0;
  inset-inline-end: 0;
}

.popup__text {
  display: block;
  margin: 0;
  font-weight: 800;
  font-size: 24px;
  text-align: center;
  text-transform: uppercase;
}

.visually-hidden {
  position: absolute;
  margin: -1px;
  border: 0;
  padding: 0;
  overflow: hidden;
  clip: rect(0 0 0 0);
  inline-size: 1px;
  block-size: 1px;
}
